"""Reject AI attribution in a commit message.

Two shapes are attribution: a Co-authored-by: trailer with any value, and a
"Generated with [" or "Generated by [" footer, optionally after the robot
emoji. A subject that mentions a tool in passing is fine. The commit-msg hook
gets the raw message file, so lines starting with # are skipped and nothing
after the scissors line of git commit -v is read. The message path comes from
argv[1].
"""

import re
import sys
from pathlib import Path
from typing import Final

ATTRIBUTION: Final[re.Pattern[str]] = re.compile(
    r"^(co-authored-by:|\s*(\U0001F916\s*)?generated (with|by) \[)", re.IGNORECASE
)
"""A Co-authored-by: trailer or a Generated with/by [ footer at the start of a line."""

SCISSORS: Final[str] = "# ------------------------ >8 ------------------------"
"""The line below which git commit -v appends the diff."""


def main() -> int:
    """Report attribution lines in the message file; return 1 if there is one."""
    path = Path(sys.argv[1])
    problems: list[str] = []
    for number, line in enumerate(
        path.read_text(encoding="utf-8", errors="replace").splitlines(), start=1
    ):
        if line == SCISSORS:
            break
        if not line.startswith("#") and ATTRIBUTION.match(line):
            problems.append(
                f"{path}:{number}: AI attribution not allowed: {line.strip()}"
            )

    for problem in problems:
        print(problem, file=sys.stderr)
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
